const fs = require('fs');
const QUEUE = '/agency/deals-queue.json';
const LOG = '/agency/deals-log.json';
const PENDING = '/agency/deals-pending.json';
let queue = [];
try { queue = (JSON.parse(fs.readFileSync(QUEUE, 'utf8')).deals || []); } catch (e) {}
let posted = new Set();
try {
  const data = JSON.parse(fs.readFileSync(LOG, 'utf8'));
  (data.entries || []).forEach(en => { if (en.status === 'posted' && en.product_url) posted.add(en.product_url); });
} catch (e) {}
const deal = queue.find(d => d && (d.affiliate_url || d.product_url) && !posted.has(d.product_url || d.affiliate_url));
if (!deal) return [];
try { fs.writeFileSync(PENDING, JSON.stringify({ deal, ts: new Date().toISOString() })); } catch (e) {}
return [{ json: {
  name: (deal.name || '').toString().trim(),
  category: (deal.category || '').toString().trim(),
  product_url: (deal.product_url || '').toString().trim(),
  affiliate_url: (deal.affiliate_url || deal.product_url || '').toString().trim(),
  price_bdt: (deal.price_bdt || '').toString().trim(),
  note: (deal.note || '').toString().trim()
} }];

let raw = '';
try { raw = $input.first().json.candidates[0].content.parts.map(p => p.text || '').join(''); } catch (e) {}
raw = raw.replace(/```json|```/g, '').trim();
const start = raw.indexOf('{'), end = raw.lastIndexOf('}');
let orig = {};
try { orig = $('Pick Deal').item.json || {}; } catch (e) {}
try {
  const j = JSON.parse(raw.slice(start, end + 1));
  const post_text = (j.post_text || '').toString().trim();
  if (!post_text) return [];
  return [{ json: { post_text, name: orig.name || '', category: orig.category || '',
    product_url: orig.product_url || '', affiliate_url: orig.affiliate_url || '',
    price_bdt: orig.price_bdt || '' } }];
} catch (e) { return []; }

const fb = $input.first().json || {};
let orig = {};
try { orig = $('Parse Writer').item.json || {}; } catch (e) {}
const postId = fb.id || '';
return [{ json: { post_text: orig.post_text || '', name: orig.name || '', category: orig.category || '',
  product_url: orig.product_url || '', affiliate_url: orig.affiliate_url || '', price_bdt: orig.price_bdt || '',
  post_id: postId, fb_ok: !!postId, fb_response: postId ? '' : JSON.stringify(fb).slice(0, 300) } }];

const fs = require('fs');
const LOG = '/agency/deals-log.json';
const PENDING = '/agency/deals-pending.json';
let log = { entries: [] };
try { log = JSON.parse(fs.readFileSync(LOG, 'utf8')); if (!Array.isArray(log.entries)) log.entries = []; } catch (e) {}
const items = $input.all().map(it => it.json);
const now = new Date().toISOString();
let posted = 0;
for (const it of items) {
  const status = it.fb_ok ? 'posted' : 'failed';
  if (status === 'posted') posted++;
  log.entries.push({ product_url: it.product_url || it.affiliate_url || '', name: it.name || '',
    status, ts: now, post_id: it.post_id || '' });
}
log.entries = log.entries.slice(-1000);
try { fs.writeFileSync(LOG, JSON.stringify(log, null, 2)); } catch (e) {}
try { fs.unlinkSync(PENDING); } catch (e) {}
return [{ json: { logged: items.length, posted, ts: now } }];

